# Deduplicate corpus by lowercase canonical termEn
DEDUP_MAP: Dict[str, Dict[str, str]] = {}
for entry in ACADEMIC_CORPUS:
    norm_en = entry["termEn"].strip().lower()
    if norm_en not in DEDUP_MAP:
        DEDUP_MAP[norm_en] = {
            "termEn": norm_en,
            "termAr": entry["termAr"].strip(),
            "partOfSpeech": entry.get("partOfSpeech", "").strip(),
            "shortDefinition": entry.get("shortDefinition", "").strip()
        }

FINAL_CORPUS: List[Dict[str, str]] = list(DEDUP_MAP.values())


# =============================================================================
# INGESTION & COMPILATION ENGINE
# =============================================================================

def ensure_general_terms_table(cur: sqlite3.Cursor):
    """Creates the general_terms table and unique case-insensitive index if absent."""
    cur.execute("""
        CREATE TABLE IF NOT EXISTS `general_terms` (
            `id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,
            `termEn` TEXT COLLATE NOCASE NOT NULL,
            `termAr` TEXT NOT NULL,
            `partOfSpeech` TEXT,
            `shortDefinition` TEXT
        );
    """)
    cur.execute("""
        CREATE UNIQUE INDEX IF NOT EXISTS `index_general_terms_termEn` 
        ON `general_terms` (`termEn`);
    """)


def ingest_academic_corpus(db_path: str, verbose: bool = True) -> Tuple[int, int]:
    """
    Ingests the curated AWL & scientific prose corpus into general_terms table.
    Uses INSERT OR IGNORE over the unique index index_general_terms_termEn for strict idempotency.
    Returns: (inserted_count, total_count)
    """
    if not os.path.exists(db_path):
        raise FileNotFoundError(f"Database asset file not found at: {db_path}")

    start_time = time.perf_counter()
    conn = sqlite3.connect(db_path)
    cur = conn.cursor()

    ensure_general_terms_table(cur)

    cur.execute("SELECT COUNT(*) FROM general_terms;")
    initial_count = cur.fetchone()[0]

    insert_rows = [
        (e["termEn"], e["termAr"], e["partOfSpeech"], e["shortDefinition"])
        for e in FINAL_CORPUS
    ]

    cur.executemany("""
        INSERT OR IGNORE INTO general_terms (termEn, termAr, partOfSpeech, shortDefinition)
        VALUES (?, ?, ?, ?);
    """, insert_rows)

    conn.commit()

    # Re-analyze index statistics for sub-5ms lookup performance
    cur.execute("ANALYZE general_terms;")
    conn.commit()

    cur.execute("SELECT COUNT(*) FROM general_terms;")
    total_count = cur.fetchone()[0]
    inserted_count = total_count - initial_count

    elapsed_ms = (time.perf_counter() - start_time) * 1000

    if verbose:
        print("=" * 65)
        print(" AWL & SCIENTIFIC ACADEMIC PROSE INGESTION COMPLETE")
        print("=" * 65)
        print(f" Database:        {db_path}")
        print(f" Corpus Size:     {len(FINAL_CORPUS)} terms")
        print(f" Initial Terms:   {initial_count}")
        print(f" Newly Inserted:  {inserted_count}")
        print(f" Total Terms:     {total_count}")
        print(f" Execution Time:  {elapsed_ms:.2f} ms")
        print("=" * 65)

    # Verification of key academic terms
    verify_terms = [
        "methodology", "hypothesis", "consequently", "significant",
        "evaluate", "framework", "parameters", "criteria",
        "considerations", "furthermore", "exhibit", "underlying"
    ]
    if verbose:
        print("\n[Verification] Validating High-Frequency Academic Term Lookups:")
        for vt in verify_terms:
            t0 = time.perf_counter()
            cur.execute("SELECT termEn, termAr, partOfSpeech FROM general_terms WHERE LOWER(termEn) = LOWER(?) LIMIT 1;", (vt,))
            row = cur.fetchone()
            t_lookup = (time.perf_counter() - t0) * 1000
            if row:
                print(f"  [OK] '{row[0]}' -> '{row[1]}' ({row[2]}) [{t_lookup:.3f} ms]")
            else:
                print(f"  [FAIL] MISSING: '{vt}'")
                raise AssertionError(f"Crucial term '{vt}' missing from general_terms!")

    conn.close()
    return inserted_count, total_count


def main():
    parser = argparse.ArgumentParser(description="Ingest Academic Word List into Malhoutha's database.")
    parser.add_argument("-d", "--db", default=DEFAULT_DB_PATH, help="Path to SQLite database asset.")
    parser.add_argument("-q", "--quiet", action="store_true", help="Quiet output mode.")
    args = parser.parse_args()

    ingest_academic_corpus(db_path=args.db, verbose=not args.quiet)


if __name__ == "__main__":
    main()
